textColor:
{{
  (() => {
    const currentTab = appsmith.store.tab_achats || 'A_COMMANDER';

    // Règle d'alerte texte uniquement sur l'onglet À COMMANDER
    if (currentTab === 'A_COMMANDER') {
      const poolData = Array.isArray(Get_Achats_Pool.data) ? Get_Achats_Pool.data : [];
      const aujourdhui = moment().startOf('day');

      // Filtrer les pièces à commander pour ce fournisseur
      const articlesACommander = poolData.filter(r => 
        (currentItem.ID_Fournisseur === 'TOUS' || (r.ID_Fournisseur || 'NON_ASSIGNE') === currentItem.ID_Fournisseur) &&
        ['À COMMANDER', 'A COMMANDER'].includes((r.Statut_Achat || '').toUpperCase()) &&
        r.Date_Demande
      );

      let aRetardClientAtelier = false; // Retard > 8 jours pour une commande Client ou un OR Atelier
      let aRetardStock = false;         // Retard > 8 jours uniquement pour du Stock Magasin

      articlesACommander.forEach(r => {
        const diffJours = aujourdhui.diff(moment(r.Date_Demande).startOf('day'), 'days');

        if (diffJours > 8) {
          // Vérification si la pièce est destinée au stock ou à un client/atelier
          const estDestineAuStock = !r.ID_Intervention && !r.ID_Commande_Client && (r.Destination === '📦 STOCK MAGASIN' || !r.Destination);

          if (estDestineAuStock) {
            aRetardStock = true;
          } else {
            aRetardClientAtelier = true;
          }
        }
      });

      // Le rouge prévaut s'il y a au moins une pièce Client/Atelier en retard
      if (aRetardClientAtelier) return "#dc2626"; // Rouge
      if (aRetardStock) return "#d97706";         // Orange
    }

    return "#231F20"; // Couleur de texte sombre par défaut
  })()
}}
